let tick = floor(t*24.0);
let line = floor(p.y*480.0);
let drift = noise(vec2<f32>(line*0.05,tick));
let band = pow(0.5+0.5*cos(6.28318*(p.y-fract(t/9.0))),24.0);
let x = p.x+cable_noise*(drift-0.5)*(0.003+band*0.016);
let uv = vec2<f32>(x/1.46+0.5,0.5-p.y/0.86);
let grid = uv*vec2<f32>(40.0,25.0);
let col = i32(floor(grid.x));
let row = i32(floor(grid.y));
let j = col-select(0,4,row==1);
let k = u32(clamp(j,0,39))/4u;
var word = 0u;
if (row==1 && j>=0 && j<32) {
 let a = vec4<u32>(0x01010101u,0x0002181au,0x1a180d18u,0x0b0c0003u);
 let b = vec4<u32>(0x04000506u,0x07080200u,0x090a0001u,0x01010100u);
 word = select(a[k%4u],b[k%4u],k>=4u);
}
if (row==4 && k<2u) { word = select(0x0b0c060du,0x0e0f0000u,k==1u); }
if (row==5 && k<4u) {
 word = vec4<u32>(0x10110012u,0x0b081314u,0x00150203u,0x04151600u)[k];
}
if (row==6 && k<3u) {
 word = vec4<u32>(0x0a110017u,0x18141800u,0x10110000u,0u)[k];
}
if (row==7 && k==0u) { word = 0x0b191300u; }
let count = i32(floor(fract(t/12.0)*88.0));
let pos = (row-8)*40+col;
var id = (word>>((3u-u32(clamp(j,0,39))%4u)*8u))&255u;
if (pos>=0 && pos<count) { id = vec3<u32>(2u,3u,4u)[u32(pos)%3u]; }
var bits = 0u;
if (id<8u) {
 bits = select(vec4<u32>(0u,0x05e5e50u,0x788887u,0x68e996u)[id%4u],vec4<u32>(0x99f111u,0xe9e99eu,0x699f99u,0x78611eu)[id%4u],id>=4u);
} else if (id<16u) {
 bits = select(vec4<u32>(0xe4444eu,0x999996u,0x69124fu,0xe99e99u)[id%4u],vec4<u32>(0xf8e88fu,0xe9999eu,0x996444u,0x000044u)[id%4u],id>=12u);
} else if (id<24u) {
 bits = select(vec4<u32>(0x4c444eu,0x699996u,0xe99e88u,0x9ddbb9u)[id%4u],vec4<u32>(0xe44444u,0xaa0000u,0x040046u,0x788b97u)[id%4u],id>=20u);
} else { bits = vec3<u32>(0x699996u,0x999996u,0x9ff999u)[min(id-24u,2u)]; }
let px = vec2<u32>(fract(grid)*vec2<f32>(5.0,8.0));
let lit = f32((bits>>(4u*(5u-min(px.y,5u))+3u-min(px.x,3u)))&1u);
let glyph = select(0.0,lit,px.x<4u && px.y<6u);
let area = fill(sd_box(uv-0.5,vec2<f32>(0.5)));
let cursor = select(0.0,1.0,pos==count && fract(t*1.5)<0.5);
let blue = mix(c2,c4*0.9,1.0-area);
let snow = hash(vec2<f32>(floor(x*610.0)+tick,line));
let signal = mix(blue,c3,max(cursor,glyph)*area);
let beam = 1.0-scanlines*0.23*(0.5+0.5*cos(p.y*3015.9));
let rf = mix(signal,c1,cable_noise*snow*0.16);
return mix(bg,mix(rf,c5,cable_noise*(0.04+0.19*band)*pow(snow,5.0))*beam,strength);
